svg.script:
(() => {
  const svg = document.documentElement;
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  const themeFor = (value) => {
    // -2/-1 use the turquoise family present in SkyjoCard.jsx; 0 stays blue.
    if (value <= -1) return { pattern:'mosaicCyan', primary:'#0891b2', secondary:'#06b6d4' };
    if (value === 0) return { pattern:'mosaicBlue', primary:'#2563eb', secondary:'#3b82f6' };
    if (value <= 4) return { pattern:'mosaicGreen', primary:'#059669', secondary:'#10b981' };
    if (value <= 8) return { pattern:'mosaicYellow', primary:'#ca8a04', secondary:'#eab308' };
    return { pattern:'mosaicRed', primary:'#dc2626', secondary:'#ef4444' };
  };

  const slots = [0,1,2,3,4].map(i => ({
    group: document.getElementById('slot' + i),
    text: document.getElementById('num' + i),
    emboss: document.getElementById('num' + i + 'Emboss'),
    cornerTL: document.getElementById('num' + i + 'TL'),
    cornerBR: document.getElementById('num' + i + 'BR'),
    card: document.getElementById('num' + i + 'Card'),
    halo: document.getElementById('num' + i + 'Halo')
  }));

  let last = [12,4,-1,8,10];

  function randomValue() {
    // Tirage uniforme parmi les 15 valeurs : -2, -1, 0 ... 12.
    return Math.floor(Math.random() * 15) - 2;
  }

  function applyValue(slot, value) {
    const theme = themeFor(value);
    const label = String(value);
    slot.text.textContent = label;
    slot.emboss.textContent = label;
    slot.cornerTL.textContent = label;
    slot.cornerBR.textContent = label;
    slot.card.setAttribute('fill', `url(#${theme.pattern})`);
    slot.halo.setAttribute('fill', theme.secondary);
    slot.cornerTL.setAttribute('fill', theme.primary);
    slot.cornerBR.setAttribute('fill', theme.primary);
  }

  function rerollSlot(slot, index) {
    let value;
    let guard = 0;
    do {
      value = randomValue();
      guard++;
    } while ((value === last[index] || last.some((v,j) => j !== index && v === value)) && guard < 30);
    last[index] = value;

    if (reduceMotion) {
      applyValue(slot, value);
      return;
    }

    slot.group.classList.remove('is-changing');
    void slot.group.getBoundingClientRect();
    slot.group.classList.add('is-changing');
    slot.text.style.opacity = '.08';
    slot.emboss.style.opacity = '.08';

    setTimeout(() => {
      applyValue(slot, value);
      slot.text.style.opacity = '1';
      slot.emboss.style.opacity = '.48';
    }, 155);

    setTimeout(() => slot.group.classList.remove('is-changing'), 310);
  }

  if (!reduceMotion) {
    const intervals = [1750, 2130, 1910, 2290, 2020];
    slots.forEach((slot, i) => {
      setTimeout(() => {
        rerollSlot(slot, i);
        setInterval(() => rerollSlot(slot, i), intervals[i]);
      }, 350 + i * 160);
    });
  }

  function launch() {
    svg.classList.remove('launching');
    void svg.getBoundingClientRect();
    svg.classList.add('launching');

    const halo = document.getElementById('tapHalo');
    if (!reduceMotion && halo.animate) {
      halo.animate(
        [
          { r:62, opacity:.78, strokeWidth:5 },
          { r:108, opacity:0, strokeWidth:1 }
        ],
        { duration:560, easing:'cubic-bezier(.15,.75,.25,1)' }
      );
    }

    slots.forEach((slot, i) => rerollSlot(slot, i));

    svg.dispatchEvent(new CustomEvent('skyjo-launch', {
      bubbles:true,
      detail:{ source:'animated-svg-button' }
    }));

    setTimeout(() => svg.classList.remove('launching'), 650);
  }

  svg.addEventListener('click', launch);
  svg.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      launch();
    }
  });
})();
